 window.addEventListener('keydown',ev=>{const k=ev.key.toLowerCase();if(dialog.open||$('#welcome').open||/input|select|textarea/i.test(ev.target.tagName))return;if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','e'].includes(k)){ev.preventDefault();if(k==='e'){const z=zones.find(z=>Math.hypot(z.x-player.x,z.y-player.y)<65);if(z)visit(z);else toast('Acércate a un personaje o usa la lista de lugares.');}else keys.add(k);}});
 window.addEventListener('keyup',ev=>keys.delete(ev.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());window.addEventListener('pagehide',()=>{state.position={...player};save();});
 canvas.addEventListener('click',ev=>{const r=canvas.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width*960,y=(ev.clientY-r.top)/r.height*600;const z=zones.find(z=>Math.hypot(z.x-x,z.y-y)<45);if(z)walkTo({x:z.x,y:z.y+32},z);else{if(blockedPoint(x,y)){toast('Camina por los senderos para acercarte.');return;}walkTo({x,y});}});
 document.querySelectorAll('[data-move]').forEach(b=>{const map={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'},key=map[b.dataset.move];b.addEventListener('pointerdown',ev=>{ev.preventDefault();b.setPointerCapture(ev.pointerId);keys.add(key);});['pointerup','pointercancel','lostpointercapture'].forEach(event=>b.addEventListener(event,()=>keys.delete(key)));});
 $('#interact-mobile').onclick=()=>{const z=zones.find(z=>Math.hypot(z.x-player.x,z.y-player.y)<65);z?visit(z):toast('Acércate a un personaje.');};
 $('#start-game').onclick=()=>{state.seenWelcome=true;save();$('#welcome').close();};
 ui();save();requestAnimationFrame(world);if(!state.seenWelcome)$('#welcome').showModal();
